stepxmp.codeblock:
:root {
  --opend-accent: #1f5fbf;      /* links and highlights */
  --opend-text: #14213d;
  --opend-muted: #52607a;       /* short descriptions, secondary text */
  --opend-surface: #ffffff;     /* page background */
  --opend-surface-alt: #f2f5fa; /* code, notes, table headers */
  --opend-border: #d9e0ea;
  --opend-warn: #b45309;        /* warning, caution and danger notes */
  --opend-cond: #7c3aed;        /* condition markers in the staff view */
  --opend-font: system-ui, sans-serif;
  --opend-mono: ui-monospace, Menlo, monospace;
}
@media (prefers-color-scheme: dark) {
  :root { --opend-surface: #10151d; --opend-text: #e6ebf2; }
}
